import{_ as e,o as s,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"文王","description":"","frontmatter":{"title":"文王","date":"2026-11-09T00:00:00.000Z","seq":1,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/文王.md","filePath":"blogs/诗经·大雅/文王.md"}'),p={name:"blogs/诗经·大雅/文王.md"};function c(l,a,r,n,_,m){return s(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="文王" tabindex="-1">文王 <a class="header-anchor" href="#文王" aria-label="Permalink to &quot;文王&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　文王之什</p><div class="poem"><p class="poem-stanza">文王在上，于昭于天。周虽旧邦，其命维新。有周不显，帝命不时。文王陟降，在帝左右。</p><p class="poem-stanza">亹亹文王，令闻不已。陈锡哉周，侯文王孙子。文王孙子，本支百世，凡周之士，不显亦世。</p><p class="poem-stanza">世之不显，厥犹翼翼。思皇多士，生此王国。王国克生，维周之桢；济济多士，文王以宁。</p><p class="poem-stanza">穆穆文王，于缉熙敬止。假哉天命。有商孙子。商之孙子，其丽不亿。上帝既命，侯于周服。</p><p class="poem-stanza">侯服于周，天命靡常。殷士肤敏。裸将于京。厥作裸将，常服黼冔。王之荩臣。无念尔祖。</p><p class="poem-stanza">无念尔祖，聿修厥德。永言配命，自求多福。殷之未丧师，克配上帝。宜鉴于殷，骏命不易！</p><p class="poem-stanza">命之不易，无遏尔躬。宣昭义问，有虞殷自天。上天之载，无声无臭。仪刑文王，万邦作孚。</p></div>',3)])])}const u=e(p,[["render",c]]);export{d as __pageData,u as default};
